#include <arpa/inet.h>
#include <errno.h>
#include <netinet/in.h>
#include <stdio.h>
#include <string.h>
#include <sys/socket.h>
#include <unistd.h>

int main(void) {
    int s = socket(AF_INET, SOCK_STREAM, 0);
    struct sockaddr_in a = {.sin_family = AF_INET, .sin_port = htons(80)};
    inet_pton(AF_INET, "127.0.0.1", &a.sin_addr);
    if (bind(s, (struct sockaddr *)&a, sizeof a) < 0) {
        printf("bind to port 80: %s\n", strerror(errno));
        return 1;
    }
    printf("bound to port 80\n");
    return 0;
}

#include <security/pam_appl.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

static int conv(int n, const struct pam_message **msg, struct pam_response **resp, void *data) {
    *resp = calloc(n, sizeof **resp);
    for (int i = 0; i < n; i++)
        (*resp)[i].resp = strdup("secret");     /* answer every prompt */
    return PAM_SUCCESS;
}

int main(int argc, char **argv) {
    struct pam_conv c = {conv, NULL};
    pam_handle_t *h;
    int r = pam_start("lab-pam", argv[1], &c, &h);   /* service name = file in /etc/pam.d */
    if (r == PAM_SUCCESS)
        r = pam_authenticate(h, 0);                  /* run the "auth" stack */
    printf("user %-8s -> %s\\n", argv[1], pam_strerror(h, r));
    pam_end(h, r);
    return r != PAM_SUCCESS;
}
